<?php
/**
 * Independent DAT parser. Used for the structural check (parse generated bytes back),
 * the DAT viewer, uploading historical files and SRS / annual consolidation.
 */
class DatReader
{
    public static function splitLine($line, $delim)
    {
        $out = array();
        $quoted = array();
        $cur = '';
        $inQ = false;
        $wasQ = false;
        $len = strlen($line);
        for ($i = 0; $i < $len; $i++) {
            $ch = $line[$i];
            if ($inQ) {
                if ($ch === '"') {
                    if ($i + 1 < $len && $line[$i + 1] === '"') {
                        $cur .= '"';
                        $i++;
                    } else {
                        $inQ = false;
                    }
                } else {
                    $cur .= $ch;
                }
            } else {
                if ($ch === '"' && $cur === '') {
                    $inQ = true;
                    $wasQ = true;
                } elseif ($ch === $delim) {
                    $out[] = $cur;
                    $quoted[] = $wasQ;
                    $cur = '';
                    $wasQ = false;
                } else {
                    $cur .= $ch;
                }
            }
        }
        $out[] = $cur;
        $quoted[] = $wasQ;
        return array($out, $quoted);
    }

    /** Find the spec record whose literal fields match the start of the line. */
    private static function matchRecord($spec, $fields, $vars)
    {
        foreach ($spec['records'] as $r) {
            $ok = true;
            $checked = 0;
            foreach ($r['fields'] as $i => $f) {
                if ($checked >= 2) {
                    break;
                }
                $expr = $f['source_expr'];
                if (strpos($expr, 'lit:') === 0) {
                    $want = substr($expr, 4);
                } elseif (strpos($expr, 'tpl:') === 0) {
                    $tpl = substr($expr, 4);
                    $re = '/^' . preg_replace('/\\\\\{\w+\\\\\}/', '[0-9A-Z]+', preg_quote($tpl, '/')) . '$/';
                    if (!isset($fields[$i]) || !preg_match($re, $fields[$i])) {
                        $ok = false;
                    }
                    $checked++;
                    continue;
                } else {
                    break;
                }
                if (!isset($fields[$i]) || $fields[$i] !== $want) {
                    $ok = false;
                    break;
                }
                $checked++;
            }
            if ($ok && $checked > 0) {
                return $r;
            }
        }
        return null;
    }

    /**
     * Parse bytes with a layout. Returns array('records' => [...], 'issues' => [...], 'rows' => detail rows normalised,
     * 'header' => assoc, 'controls' => [assoc], 'line_ending' => 'CRLF'|'LF'|'mixed', 'has_bom' => bool, 'non_ascii' => bool)
     */
    public static function parse($bytes, $spec)
    {
        $issues = array();
        $issue = function ($sev, $code, $line, $field, $msg) use (&$issues) {
            $issues[] = array('severity' => $sev, 'code' => $code, 'record_no' => $line, 'field_key' => $field, 'message' => $msg);
        };
        $hasBom = substr($bytes, 0, 3) === "\xEF\xBB\xBF";
        if ($hasBom) {
            $issue('error', 'BOM', 1, null, 'The file starts with a UTF-8 byte-order mark.');
            $bytes = substr($bytes, 3);
        }
        $crlf = substr_count($bytes, "\r\n");
        $lf = substr_count($bytes, "\n") - $crlf;
        $eol = $crlf && !$lf ? 'CRLF' : ($lf && !$crlf ? 'LF' : ($crlf || $lf ? 'mixed' : 'none'));
        $nonAscii = (bool)preg_match('/[^\x09\x0A\x0D\x20-\x7E]/', $bytes);
        $text = str_replace("\r\n", "\n", $bytes);
        $endsWithNewline = substr($text, -1) === "\n";
        $lines = explode("\n", rtrim($text, "\n"));
        $records = array();
        $rows = array();
        $header = null;
        $controls = array();
        $delim = $spec['delimiter'];
        $start = (int)$spec['column_header_row'] === 1 ? 1 : 0;
        foreach ($lines as $idx => $line) {
            $lineNo = $idx + 1;
            if ($idx < $start) {
                continue;
            }
            if ($line === '') {
                $issue('error', 'EMPTY_LINE', $lineNo, null, 'Line ' . $lineNo . ' is empty.');
                continue;
            }
            list($fields, $quoted) = self::splitLine($line, $delim);
            $rec = (int)$spec['column_header_row'] === 1 ? self::detailOf($spec) : self::matchRecord($spec, $fields, array());
            if (!$rec) {
                $issue('error', 'UNKNOWN_RECORD', $lineNo, null, 'Line ' . $lineNo . ' starts with "' . $fields[0] . '", which is not a record type of this layout.');
                continue;
            }
            $expected = count($rec['fields']);
            if (count($fields) !== $expected) {
                $issue('error', 'FIELD_COUNT', $lineNo, null, 'Line ' . $lineNo . ' (' . $rec['record_code'] . ') has ' . count($fields) . ' fields; the layout defines ' . $expected . '.');
            }
            $assoc = array();
            $norm = array();
            foreach ($rec['fields'] as $i => $f) {
                $v = isset($fields[$i]) ? $fields[$i] : '';
                $assoc[$f['field_key']] = $v;
                $wasQuoted = isset($quoted[$i]) ? $quoted[$i] : false;
                if ($f['quote_mode'] === 'always' && !$wasQuoted) {
                    $issue('error', 'QUOTE', $lineNo, $f['field_key'], $f['label'] . ' should be enclosed in double quotes.');
                } elseif ($f['quote_mode'] === 'never' && $wasQuoted) {
                    $issue('error', 'QUOTE', $lineNo, $f['field_key'], $f['label'] . ' should not be quoted.');
                }
                self::checkValue($f, $v, $lineNo, $issue);
                if (strpos($f['source_expr'], 'row.') === 0) {
                    $k = substr($f['source_expr'], 4);
                    $norm[$k] = $f['data_type'] === 'amount' ? Money::fromDb($v === '' ? '0' : $v) : ($f['data_type'] === 'rate' ? self::rateBack($v, $f['fmt']) : ($f['data_type'] === 'date' ? self::dateBack($v) : $v));
                }
            }
            $entry = array('line' => $lineNo, 'record_code' => $rec['record_code'], 'role' => $rec['role'], 'fields' => $assoc, 'field_count' => count($fields), 'expected' => $expected);
            $records[] = $entry;
            if ($rec['role'] === 'detail') {
                $rows[] = $norm;
            } elseif ($rec['role'] === 'header') {
                if ($header !== null) {
                    $issue('error', 'MULTI_HEADER', $lineNo, null, 'More than one header record.');
                }
                if ($rows) {
                    $issue('error', 'ORDER', $lineNo, null, 'Header record appears after detail records.');
                }
                $header = $assoc;
            } else {
                $controls[] = $assoc;
            }
        }
        $hasHeaderSpec = false;
        $hasControlSpec = false;
        foreach ($spec['records'] as $r) {
            $hasHeaderSpec = $hasHeaderSpec || $r['role'] === 'header';
            $hasControlSpec = $hasControlSpec || $r['role'] === 'control';
        }
        if ($hasHeaderSpec && $header === null) {
            $issue('error', 'NO_HEADER', 1, null, 'The header record is missing.');
        }
        if ($hasControlSpec && !$controls) {
            $issue('error', 'NO_CONTROL', count($lines), null, 'The control record is missing.');
        }
        if ($records && $hasControlSpec && end($records)['role'] !== 'control') {
            $issue('error', 'ORDER', count($lines), null, 'The control record must be the last line.');
        }
        return array('records' => $records, 'rows' => $rows, 'header' => $header, 'controls' => $controls, 'issues' => $issues,
            'line_ending' => $eol, 'has_bom' => $hasBom, 'non_ascii' => $nonAscii, 'ends_with_newline' => $endsWithNewline, 'line_count' => count($lines));
    }

    private static function detailOf($spec)
    {
        foreach ($spec['records'] as $r) {
            if ($r['role'] === 'detail') {
                return $r;
            }
        }
        return null;
    }

    private static function rateBack($v, $fmt)
    {
        if ($v === '') {
            return '0.0000';
        }
        $u = Money::rateUnits($v);
        if ($u === null) {
            return $v;
        }
        if ($fmt === 'frac2') {
            $u *= 100;
        }
        return Money::rateString($u);
    }

    private static function dateBack($v)
    {
        if (preg_match('/^(\d{2})\/(\d{2})\/(\d{4})$/', $v, $m)) {
            return $m[3] . '-' . $m[1] . '-' . $m[2];
        }
        return $v;
    }

    private static function checkValue($f, $v, $lineNo, $issue)
    {
        $label = $f['label'];
        if ((int)$f['required'] === 1 && $v === '') {
            $issue('error', 'REQUIRED', $lineNo, $f['field_key'], $label . ' is empty.');
            return;
        }
        if ($v === '') {
            return;
        }
        switch ($f['data_type']) {
            case 'digits':
                if (!ctype_digit($v) || ($f['max_len'] && strlen($v) !== (int)$f['max_len'])) {
                    $issue('error', 'DIGITS', $lineNo, $f['field_key'], $label . ' must be ' . $f['max_len'] . ' digits (found "' . $v . '").');
                }
                break;
            case 'amount':
                if (!preg_match('/^-?\d+(\.\d{1,2})?$/', $v)) {
                    $issue('error', 'AMOUNT', $lineNo, $f['field_key'], $label . ' "' . $v . '" is not an amount.');
                } elseif ($f['fmt'] === '2dp' && !preg_match('/\.\d{2}$/', $v)) {
                    $issue('error', 'AMOUNT', $lineNo, $f['field_key'], $label . ' "' . $v . '" should have two decimals.');
                }
                break;
            case 'rate':
                if (!preg_match('/^\d+(\.\d+)?$/', $v)) {
                    $issue('error', 'RATE', $lineNo, $f['field_key'], $label . ' "' . $v . '" is not a rate.');
                }
                break;
            case 'date':
                if (!preg_match('/^(\d{2})\/(\d{2})\/(\d{4})$/', $v, $m) || !checkdate((int)$m[1], (int)$m[2], (int)$m[3])) {
                    $issue('error', 'DATE', $lineNo, $f['field_key'], $label . ' "' . $v . '" is not a valid MM/DD/YYYY date.');
                }
                break;
            case 'int':
                if (!ctype_digit($v)) {
                    $issue('error', 'INT', $lineNo, $f['field_key'], $label . ' "' . $v . '" is not a whole number.');
                }
                break;
        }
        if ($f['max_len'] && $f['data_type'] !== 'digits' && strlen($v) > (int)$f['max_len']) {
            $issue('error', 'WIDTH', $lineNo, $f['field_key'], $label . ' exceeds ' . $f['max_len'] . ' characters.');
        }
        if (strpos($f['source_expr'], 'lit:') === 0 && $v !== substr($f['source_expr'], 4)) {
            $issue('error', 'LITERAL', $lineNo, $f['field_key'], $label . ' should be "' . substr($f['source_expr'], 4) . '".');
        }
    }

    /** Guess the layout of an uploaded DAT from its filename and first line. Returns list of [spec, tokens]. */
    public static function detect($filename, $bytes)
    {
        $first = strtok(str_replace("\r\n", "\n", $bytes), "\n");
        $found = array();
        foreach (DB::all('SELECT id, filename_pattern, form_code, schedule_code, variant_key, status FROM layout_specs WHERE status <> ? ORDER BY id', array('retired')) as $s) {
            if (!preg_match(Specs::filenameRegex($s['filename_pattern']), $filename, $tok)) {
                continue;
            }
            $spec = Specs::load($s['id']);
            list($fields) = self::splitLine((string)$first, $spec['delimiter']);
            if ((int)$spec['column_header_row'] !== 1 && !self::matchRecord($spec, $fields, array())) {
                continue;
            }
            $score = Specs::statusRank($spec['status']);
            $parsed = self::parse($bytes, $spec);
            $errs = 0;
            foreach ($parsed['issues'] as $i) {
                if ($i['severity'] === 'error') {
                    $errs++;
                }
            }
            $found[] = array('spec' => $spec, 'tokens' => $tok, 'errors' => $errs, 'score' => $score);
        }
        usort($found, function ($a, $b) {
            if ($a['errors'] !== $b['errors']) {
                return $a['errors'] - $b['errors'];
            }
            return $b['score'] - $a['score'];
        });
        return $found;
    }
}
